package com.pcguard.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="telemetry") public class Telemetry { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) @JoinColumn(name="computer_id") public Computer computer; public Instant timestamp; @Column(name="cpu_usage") public Double cpuUsage; @Column(name="cpu_temperature") public Double cpuTemperature; @Column(name="ram_total") public Long ramTotal; @Column(name="ram_used") public Long ramUsed; @Column(name="ram_available") public Long ramAvailable; @Column(name="ram_usage") public Double ramUsage; @Column(name="storage_total") public Long storageTotal; @Column(name="storage_used") public Long storageUsed; @Column(name="storage_free") public Long storageFree; @Column(name="storage_usage") public Double storageUsage; @Column(name="network_status") public String networkStatus; @Column(name="network_download") public Long networkDownload; @Column(name="network_upload") public Long networkUpload; @Column(name="process_count") public Integer processCount; public Long uptime; }
